// Reads the whole-file text (from the "Extract CSV Text" node) and tolerantly
// parses it. Ragged rows (too few / too many columns) are repaired and
// flagged - never dropped. Mirrors pipeline.py's ingest() function.

const text = $input.first().json.data;

function splitCsvLine(line) {
  const fields = [];
  let cur = '';
  let inQuotes = false;
  for (let i = 0; i < line.length; i++) {
    const ch = line[i];
    if (inQuotes) {
      if (ch === '"') {
        if (line[i + 1] === '"') { cur += '"'; i++; }
        else { inQuotes = false; }
      } else {
        cur += ch;
      }
    } else if (ch === '"') {
      inQuotes = true;
    } else if (ch === ',') {
      fields.push(cur);
      cur = '';
    } else {
      cur += ch;
    }
  }
  fields.push(cur);
  return fields;
}

const lines = text.split(/\r\n|\n|\r/).filter((l) => l.length > 0);
if (lines.length === 0) return [];

const header = splitCsvLine(lines[0]).map((h) => h.trim());
const nExpected = header.length;
const results = [];

for (let i = 1; i < lines.length; i++) {
  const flags = [];
  let fields = splitCsvLine(lines[i]);
  if (fields.every((f) => f.trim() === '')) continue; // blank line, not a lead row

  if (fields.length < nExpected) {
    flags.push(`structural: expected ${nExpected} columns, got ${fields.length} at line ${i + 1}`);
    while (fields.length < nExpected) fields.push('');
  } else if (fields.length > nExpected) {
    const notesIdx = header.indexOf('raw_notes') >= 0 ? header.indexOf('raw_notes') : nExpected - 2;
    const head = fields.slice(0, notesIdx);
    const hasTailCol = nExpected - notesIdx - 1 === 1;
    const tail = hasTailCol ? fields[fields.length - 1] : null;
    const mergedNotes = fields.slice(notesIdx, fields.length - (hasTailCol ? 1 : 0)).join(',');
    let repaired = [...head, mergedNotes];
    if (tail !== null) repaired.push(tail);
    while (repaired.length < nExpected) repaired.push('');
    fields = repaired.slice(0, nExpected);
    flags.push(`structural: expected ${nExpected} columns, got more at line ${i + 1} (auto-merged extra commas into raw_notes)`);
  }

  const row = {};
  header.forEach((h, idx) => { row[h] = fields[idx] !== undefined ? fields[idx] : ''; });
  row._line_no = i + 1;
  row._ingest_flags = flags;
  results.push({ json: row });
}

return results;

// Per-lead validation. Uses workflow static data to spot same-email
// duplicates across the whole run (soft flag, not a drop).

const staticData = $getWorkflowStaticData('node');
if (!staticData.seenEmails) staticData.seenEmails = {};

const row = $json;
const flags = [...(row._ingest_flags || [])];

const leadId = (row.lead_id || '').trim();
const name = (row.name || '').trim();
const email = (row.email || '').trim().toLowerCase();
const company = (row.company || '').trim();
const rawNotes = (row.raw_notes || '').trim();
const source = (row.source || '').trim().toLowerCase() || 'unknown';

const emailRe = /^[^@\s]+@[^@\s]+\.[^@\s]+$/;
const emailValid = emailRe.test(email);

if (!leadId) flags.push('missing lead_id');
if (!email) flags.push('missing email');
else if (!emailValid) flags.push(`malformed email: '${email}'`);
if (!company) flags.push('missing company');
if (!rawNotes) flags.push('empty raw_notes');

if (emailValid) {
  if (staticData.seenEmails[email]) {
    flags.push(`possible duplicate of ${staticData.seenEmails[email]} (same email)`);
  } else {
    staticData.seenEmails[email] = leadId || `line ${row._line_no}`;
  }
}

return {
  json: {
    lead_id: leadId || `UNKNOWN-${row._line_no}`,
    name: name || null,
    email: email || null,
    email_valid: emailValid,
    company: company || null,
    raw_notes: rawNotes || null,
    source,
    flags,
  },
};

// Enrichment step 1 (required by the brief): derive the domain from the
// email. If the email is missing/invalid, fall back to a low-confidence
// guess from the company name rather than leaving the row un-enrichable.

function guessDomainFromCompany(company) {
  if (!company) return null;
  const slug = company.toLowerCase().replace(/[^a-z0-9]/g, '');
  return slug ? `${slug}.com` : null;
}

const lead = $json;
const flags = [...lead.flags];
let domain = null;
let domainSource = null;

if (lead.email_valid) {
  domain = lead.email.split('@')[1];
  domainSource = 'email';
} else {
  domain = guessDomainFromCompany(lead.company);
  domainSource = domain ? 'inferred_from_company_name' : null;
  if (domain) flags.push(`domain guessed from company name (low confidence): ${domain}`);
  else flags.push('could not derive domain: no valid email and no company name');
}

return { json: { ...lead, domain, domain_source: domainSource, flags } };

// The "Enrich - Disify Email Check" HTTP node has onError = continueRegularOutput,
// so a network failure produces an item with an `error` field instead of
// crashing the run. Pull the lead fields from the last known-good node
// (Derive Domain) rather than trusting $json here, since a failed HTTP node
// can replace the item JSON entirely.

const lead = $('Derive Domain').item.json;
const resp = $json;
const flags = [...lead.flags];

let disposable = null;
let deliverable = null;

if (resp && resp.error) {
  flags.push(`enrichment API failed (non-fatal): ${resp.error.message || JSON.stringify(resp.error)}`);
} else if (lead.domain) {
  disposable = resp.disposable !== undefined ? resp.disposable : null;
  deliverable = resp.dns !== undefined ? resp.dns : (resp.format !== undefined ? resp.format : null);
}

return { json: { ...lead, domain_is_disposable: disposable, domain_deliverable: deliverable, flags } };

