// The "Prioritize - OpenRouter LLM" HTTP node also has onError =
// continueRegularOutput and retryOnFail enabled, so a model/API failure
// flags the row instead of stopping the run. Same pattern as above: pull
// lead fields from the last known-good node.

const lead = $('Merge Enrichment Result').item.json;
const resp = $json;
const flags = [...lead.flags];
let priority = 'unknown';
let summary = 'LLM enrichment failed for this row.';

if (resp && resp.error) {
  flags.push(`LLM call failed, row flagged not dropped: ${resp.error.message || JSON.stringify(resp.error)}`);
} else {
  try {
    let content = resp.choices[0].message.content.trim();
    content = content.replace(/^```(json)?/i, '').replace(/```$/, '').trim();
    const parsed = JSON.parse(content);
    const p = String(parsed.priority || '').toLowerCase().trim();
    if (!['high', 'medium', 'low'].includes(p)) throw new Error(`unexpected priority value: ${p}`);
    priority = p;
    summary = String(parsed.summary || '').slice(0, 300);
  } catch (e) {
    flags.push(`LLM response could not be parsed, row flagged not dropped: ${e.message}`);
  }
}

const status = flags.length ? 'flagged' : 'ok';

return {
  json: {
    lead_id: lead.lead_id,
    name: lead.name,
    email: lead.email,
    email_valid: lead.email_valid,
    company: lead.company,
    domain: lead.domain,
    domain_source: lead.domain_source,
    domain_is_disposable: lead.domain_is_disposable,
    raw_notes: lead.raw_notes,
    source: lead.source,
    priority,
    summary,
    status,
    flags: flags.join(' | '),
  },
};
